package kv

import (
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"unicode/utf8"
)

// KVValue is either string or *KVObject.
type KVValue interface{}

type KVObject struct {
	Keys   []string
	Values map[string]KVValue
}

func NewKVObject() *KVObject {
	return &KVObject{
		Keys:   []string{},
		Values: map[string]KVValue{},
	}
}

func (kv *KVObject) Has(key string) bool {
	_, ok := kv.Values[key]
	return ok
}

func (kv *KVObject) Set(key string, val KVValue) {
	if !kv.Has(key) {
		kv.Keys = append(kv.Keys, key)
	}
	kv.Values[key] = val
}

func (kv *KVObject) Delete(key string) {
	if !kv.Has(key) {
		return
	}
	delete(kv.Values, key)
	newKeys := make([]string, 0, len(kv.Keys))
	for _, k := range kv.Keys {
		if k != key {
			newKeys = append(newKeys, k)
		}
	}
	kv.Keys = newKeys
}

func (kv *KVObject) Get(key string) (KVValue, bool) {
	v, ok := kv.Values[key]
	return v, ok
}

func (kv *KVObject) GetString(key string) (string, bool) {
	v, ok := kv.Values[key]
	if !ok {
		return "", false
	}
	s, ok := v.(string)
	return s, ok
}

func (kv *KVObject) GetObject(key string) (*KVObject, bool) {
	v, ok := kv.Values[key]
	if !ok {
		return nil, false
	}
	obj, ok := v.(*KVObject)
	return obj, ok
}

// DeepClone duplicates the kv tree preserving key order.
func (kv *KVObject) DeepClone() *KVObject {
	out := NewKVObject()
	for _, k := range kv.Keys {
		v := kv.Values[k]
		switch vv := v.(type) {
		case string:
			out.Set(k, vv)
		case *KVObject:
			out.Set(k, vv.DeepClone())
		}
	}
	return out
}

// MergeFrom copies keys/values from other, respecting other's order.
func (kv *KVObject) MergeFrom(other *KVObject) {
	for _, k := range other.Keys {
		kv.Set(k, other.Values[k])
	}
}

type Token struct {
	Typ string // "{", "}", "str"
	Val string
	Idx int
}

func stripComments(s string) string {
	var b strings.Builder
	b.Grow(len(s))
	inStr := false
	escape := false
	for i := 0; i < len(s); {
		ch := s[i]
		if inStr {
			b.WriteByte(ch)
			if escape {
				escape = false
			} else {
				if ch == '\\' {
					escape = true
				} else if ch == '"' {
					inStr = false
				}
			}
			i++
			continue
		}

		if ch == '"' {
			inStr = true
			b.WriteByte(ch)
			i++
			continue
		}

		if ch == '/' && i+1 < len(s) {
			next := s[i+1]
			if next == '/' {
				i += 2
				for i < len(s) && s[i] != '\n' {
					i++
				}
				if i < len(s) {
					b.WriteByte('\n')
					i++
				}
				continue
			}
			if next == '*' {
				i += 2
				for i+1 < len(s) {
					if s[i] == '\n' {
						b.WriteByte('\n')
					}
					if s[i] == '*' && s[i+1] == '/' {
						i += 2
						break
					}
					i++
				}
				continue
			}
		}

		b.WriteByte(ch)
		i++
	}
	return b.String()
}

func tokenizeKVWithStripped(input string) ([]Token, string) {
	s := stripComments(input)
	tokens := []Token{}
	i := 0

	isWS := func(r rune) bool {
		return r == ' ' || r == '\t' || r == '\r' || r == '\n'
	}

	for i < len(s) {
		r, size := utf8.DecodeRuneInString(s[i:])
		if isWS(r) {
			i += size
			continue
		}

		if r == '{' || r == '}' {
			tokens = append(tokens, Token{Typ: string(r), Idx: i})
			i += size
			continue
		}

		if r == '"' {
			start := i
			i += size
			var out strings.Builder
			for i < len(s) {
				ch, sz := utf8.DecodeRuneInString(s[i:])
				if ch == '\\' {
					if i+sz < len(s) {
						next, nextSize := utf8.DecodeRuneInString(s[i+sz:])
						out.WriteRune(next)
						i += sz + nextSize
						continue
					}
					i += sz
					continue
				}
				if ch == '"' {
					i += sz
					break
				}
				out.WriteRune(ch)
				i += sz
			}
			tokens = append(tokens, Token{Typ: "str", Val: out.String(), Idx: start})
			continue
		}

		// unquoted token
		start := i
		var out strings.Builder
		for i < len(s) {
			ch, sz := utf8.DecodeRuneInString(s[i:])
			if isWS(ch) || ch == '{' || ch == '}' {
				break
			}
			out.WriteRune(ch)
			i += sz
		}
		if out.Len() > 0 {
			tokens = append(tokens, Token{Typ: "str", Val: out.String(), Idx: start})
		}
	}

	return tokens, s
}

func TokenizeKV(input string) []Token {
	toks, _ := tokenizeKVWithStripped(input)
	return toks
}

func expectStr(tokens []Token, idx *int) (string, error) {
	if *idx >= len(tokens) || tokens[*idx].Typ != "str" {
		return "", fmt.Errorf("expected string at token %d", *idx)
	}
	val := tokens[*idx].Val
	*idx++
	return val, nil
}

func parseObject(tokens []Token, idx *int) (*KVObject, error) {
	obj := NewKVObject()
	for *idx < len(tokens) {
		tk := tokens[*idx]
		if tk.Typ == "}" {
			*idx++
			break
		}

		key, err := expectStr(tokens, idx)
		if err != nil {
			return nil, err
		}
		if *idx >= len(tokens) {
			return nil, fmt.Errorf("unexpected EOF after key: %s", key)
		}

		next := tokens[*idx]
		if next.Typ == "{" {
			*idx++
			val, err := parseObject(tokens, idx)
			if err != nil {
				return nil, err
			}
			obj.Set(key, val)
		} else if next.Typ == "str" {
			val, err := expectStr(tokens, idx)
			if err != nil {
				return nil, err
			}
			obj.Set(key, val)
		} else {
			return nil, fmt.Errorf("unexpected token after key %s at %d", key, *idx)
		}
	}
	return obj, nil
}

func ParseKV(tokens []Token) (*KVObject, error) {
	idx := 0
	root := NewKVObject()
	for idx < len(tokens) {
		tk := tokens[idx]
		if tk.Typ == "}" {
			return nil, fmt.Errorf("unmatched '}' at top level")
		}

		key, err := expectStr(tokens, &idx)
		if err != nil {
			return nil, err
		}
		if idx >= len(tokens) {
			return nil, fmt.Errorf("unexpected EOF after key: %s", key)
		}

		next := tokens[idx]
		if next.Typ == "{" {
			idx++
			val, err := parseObject(tokens, &idx)
			if err != nil {
				return nil, err
			}
			root.Set(key, val)
		} else if next.Typ == "str" {
			val, err := expectStr(tokens, &idx)
			if err != nil {
				return nil, err
			}
			root.Set(key, val)
		} else {
			return nil, fmt.Errorf("unexpected token after top key %s", key)
		}
	}

	return root, nil
}

func ReadKVFile(absPath string) (*KVObject, error) {
	data, err := os.ReadFile(absPath)
	if err != nil {
		return nil, err
	}
	tokens, stripped := tokenizeKVWithStripped(string(data))
	obj, err := ParseKV(tokens)
	if err != nil {
		// enhance error with line/col when possible
		var idx int
		_, _ = fmt.Sscanf(err.Error(), "expected string at token %d", &idx)
		if idx >= 0 && idx < len(tokens) {
			if tokens[idx].Idx >= 0 {
				before := stripped[:tokens[idx].Idx]
				line := strings.Count(before, "\n") + 1
				lastNl := strings.LastIndex(before, "\n")
				col := tokens[idx].Idx - lastNl
				snippet := stripped[tokens[idx].Idx:]
				if len(snippet) > 80 {
					snippet = snippet[:80]
				}
				return nil, fmt.Errorf("%w (line %d, col %d) near: %s", err, line, col, strings.ReplaceAll(snippet, "\n", "\\n"))
			}
		}
		return nil, err
	}
	return obj, nil
}

func quoteKV(v string) string {
	v = strings.ReplaceAll(v, `\`, `\\`)
	v = strings.ReplaceAll(v, `"`, `\"`)
	return `"` + v + `"`
}

func kvToString(obj *KVObject, indent int) string {
	pad := strings.Repeat("\t", indent)
	var buf strings.Builder
	for _, k := range obj.Keys {
		v := obj.Values[k]
		switch vv := v.(type) {
		case string:
			buf.WriteString(fmt.Sprintf("%s%s\t\t%s\n", pad, quoteKV(k), quoteKV(vv)))
		case *KVObject:
			buf.WriteString(fmt.Sprintf("%s%s\n", pad, quoteKV(k)))
			buf.WriteString(fmt.Sprintf("%s{\n", pad))
			buf.WriteString(kvToString(vv, indent+1))
			buf.WriteString(fmt.Sprintf("%s}\n", pad))
		}
	}
	return buf.String()
}

func WriteKVFile(absPath string, obj *KVObject) error {
	content := kvToString(obj, 0)
	dir := filepath.Dir(absPath)
	if err := os.MkdirAll(dir, fs.ModePerm); err != nil {
		return err
	}
	return os.WriteFile(absPath, []byte(content), 0o644)
}

// DetectRootItems unwraps a single top-level key if it directly contains objects.
func DetectRootItems(kv *KVObject) *KVObject {
	if kv == nil {
		return NewKVObject()
	}
	if len(kv.Keys) == 1 {
		first := kv.Keys[0]
		if obj, ok := kv.GetObject(first); ok {
			return obj
		}
	}
	return kv
}

func IsObject(v KVValue) (*KVObject, bool) {
	obj, ok := v.(*KVObject)
	return obj, ok
}

// SplitWhitespace splits string by whitespace trimming outer spaces.
func SplitWhitespace(s string) []string {
	trim := strings.TrimSpace(s)
	if trim == "" {
		return []string{}
	}
	return strings.Fields(trim)
}

// ReadFileIfExists returns content or empty string if file missing.
func ReadFileIfExists(path string) (string, error) {
	data, err := os.ReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		return "", nil
	}
	return string(data), err
}

