type FieldMeta struct {
	Base              string `json:"base,omitempty"`
	FallbackLocalized string `json:"fallbackLocalized,omitempty"`
}

type PluginConfig struct {
	Pairs              []PairConfig
	FieldTable         map[string]FieldMeta
	FieldTableOrder    []string
	FieldTable2        map[string]FieldMeta
	FieldTable2Order   []string
	LocalizationFile   string
	LocalizationLookup []string
