func Run(workspaceRoot string) error {
	loaded, err := loadConfig(workspaceRoot)
	if err != nil {
		return err
	}
	cfg := loaded.cfg
	cfgDir := filepath.Dir(loaded.cfgPath)
	cfgParent := filepath.Dir(cfgDir)

	baseCandidates := uniqueNonEmpty([]string{
		workspaceRoot,
		cfgDir,
		cfgParent,
	})

	resolvePath := func(rel string, forWrite bool) string {
		// game/... 优先尝试父级工作区（避免写到 repo 内的 game 目录）
		var order []string
		if strings.HasPrefix(rel, "game/") || strings.HasPrefix(rel, "game\\") {
			seen := map[string]struct{}{}
			if cfgParent != "" {
				order = append(order, cfgParent)
				seen[cfgParent] = struct{}{}
			}
			for _, b := range baseCandidates {
				if _, ok := seen[b]; ok {
					continue
				}
				order = append(order, b)
			}
		} else {
			order = baseCandidates
		}

		for _, base := range order {
			p := filepath.Join(base, rel)
			if !forWrite {
				if _, err := os.Stat(p); err == nil {
					return p
				}
				continue
			}
			dir := filepath.Dir(p)
			if info, err := os.Stat(dir); err == nil && info.IsDir() {
				return p
			}
		}

		// fallback：若写入则优先使用最后一个候选目录，读取则落回 cfgDir
		targetBases := order
		if len(targetBases) == 0 {
			targetBases = []string{cfgDir}
		}
		if forWrite {
			return filepath.Join(targetBases[len(targetBases)-1], rel)
		}
		return filepath.Join(cfgDir, rel)
	}
	resolve := func(rel string) string {
		return resolvePath(rel, false)
	}
	resolveForWrite := func(rel string) string {
		return resolvePath(rel, true)
	}

	locPath := resolveForWrite(cfg.LocalizationFile)
	locKV := kv.NewKVObject()
	if _, err := os.Stat(locPath); err == nil {
		locKV, err = kv.ReadKVFile(locPath)
		if err != nil {
			return fmt.Errorf("read localization kv: %w", err)
		}
	}

	locText, err := kv.ReadFileIfExists(locPath)
	if err != nil {
