		for _, itemName := range rawItemOrder {
			statsItem, _ := statsItems.GetObject(itemName)
			maxLevelMap[itemName] = getMaxLevelFromStatsItem(statsItem)
			if pair.Name == "shop1_items" {
				if hero, ok := statsItem.GetString("HeroName"); ok && hero != "" {
					if maxLevelMap[itemName] > heroMaxLevel[hero] {
						heroMaxLevel[hero] = maxLevelMap[itemName]
					}
				}
			}

			res := localizeBaseItems(localizeBaseItemsParams{
				pairName:      pair.Name,
				rawItemOrder:  []string{itemName},
				statsItems:    statsItems,
				rawItems:      rawItems,
				locKV:         locKV,
				locText:       locText,
				insertByIndex: insertLocalizationByIndex,
				buildTooltip:  buildTooltipValueForField,
				getBonusOrder: func(item string) []string {
					return getBonusAttributeOrder(statsTokens, item)
				},
				insertRef: insertRef,
			})
			locText = res.locText
			if insertRef == nil && res.insertRef != nil {
				insertRef = res.insertRef
			}

			locText = expandLocalizationByLevel(expandLocalizationParams{
				rawItemOrder:  []string{itemName},
				rawItems:      rawItems,
				statsItems:    statsItems,
				locKV:         locKV,
				locText:       locText,
				insertRef:     insertRef,
				insertByIndex: insertLocalizationByIndex,
				buildTooltip:  buildTooltipValueForField,
				maxLevelMap:   maxLevelMap,
			})

			baseLuaPath := resolveForWrite(filepath.Join(
				"game/dzsj/scripts/vscripts/abilities",
				fmt.Sprintf("%s.lua", itemName),
			))

			if _, err := os.Stat(baseLuaPath); errors.Is(err, os.ErrNotExist) && fallbackLuaPath != "" {
				if data, err := os.ReadFile(fallbackLuaPath); err == nil {
					baseData := string(data)
					repl := regexp.MustCompile(`\b` + regexp.QuoteMeta(fallbackLuaName) + `\b`)
					out := repl.ReplaceAllString(baseData, itemName)
					_ = os.MkdirAll(filepath.Dir(baseLuaPath), fs.ModePerm)
					_ = os.WriteFile(baseLuaPath, []byte(out), 0o644)
				}
			}

			for lvl := 1; lvl <= maxLevelMap[itemName]; lvl++ {
				generateDerivedItemLua(baseLuaPath, lvl, false)
			}
		}

		expandItemsByLevel(expandItemsParams{
			rawItems:      rawItems,
			baseOrder:     rawItemOrder,
			maxLevelMap:   maxLevelMap,
			managedFields: managedFields,
		})

		if err := kv.WriteKVFile(ctx.rawAbs, ctx.rawItems); err != nil {
			return fmt.Errorf("write raw kv: %w", err)
		}
	}

	if err := ensureAutoCastDummies(resolve, resolveForWrite, heroMaxLevel); err != nil {
		return err
	}

	locText = normalizeTokensBlankLines(locText)
	if err := os.MkdirAll(filepath.Dir(locPath), fs.ModePerm); err != nil {
		return fmt.Errorf("ensure localization dir: %w", err)
	}
	if err := os.WriteFile(locPath, []byte(locText), 0o644); err != nil {
		return fmt.Errorf("write localization: %w", err)
	}

	if err := mergeNpcKVs(resolve, resolveForWrite); err != nil {
		return err
	}

	return nil
}

// ---------- config ----------

func loadConfig(workspaceRoot string) (*loadedConfig, error) {
	cfgName := "dzsj.kv-sync.json"
	found, err := findConfigFile(workspaceRoot, cfgName)
	if err != nil {
		return nil, err
	}
	if found == "" {
		return nil, fmt.Errorf("missing config %s", cfgName)
	}
	data, err := os.ReadFile(found)
	if err != nil {
		return nil, err
	}

	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return nil, err
	}

	cfg := &PluginConfig{}

	if pairsRaw, ok := raw["pairs"]; ok {
		if err := json.Unmarshal(pairsRaw, &cfg.Pairs); err != nil {
			return nil, fmt.Errorf("parse pairs: %w", err)
		}
	}

	if locRaw, ok := raw["localizationFile"]; ok {
		if err := json.Unmarshal(locRaw, &cfg.LocalizationFile); err != nil {
			return nil, fmt.Errorf("parse localizationFile: %w", err)
		}
	}
	if lvRaw, ok := raw["Level"]; ok {
		if err := json.Unmarshal(lvRaw, &cfg.Level); err != nil {
			return nil, fmt.Errorf("parse Level: %w", err)
		}
	}

	if ftRaw, ok := raw["fieldTable"]; ok {
		m, order, err := parseOrderedFieldMeta(ftRaw)
		if err != nil {
			return nil, fmt.Errorf("parse fieldTable: %w", err)
		}
		cfg.FieldTable = m
		cfg.FieldTableOrder = order
	}

	if ftRaw, ok := raw["fieldTable2"]; ok {
		m, order, err := parseOrderedFieldMeta(ftRaw)
		if err != nil {
			return nil, fmt.Errorf("parse fieldTable2: %w", err)
		}
		cfg.FieldTable2 = m
		cfg.FieldTable2Order = order
	}

	return &loadedConfig{cfg: cfg, cfgPath: found}, nil
}

func parseOrderedFieldMeta(raw json.RawMessage) (map[string]FieldMeta, []string, error) {
	dec := json.NewDecoder(bytes.NewReader(raw))
	tok, err := dec.Token()
	if err != nil {
		return nil, nil, err
	}
	delim, ok := tok.(json.Delim)
	if !ok || delim != '{' {
		return nil, nil, fmt.Errorf("expected object")
	}
	result := map[string]FieldMeta{}
	order := []string{}
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return nil, nil, err
		}
		key, ok := keyTok.(string)
		if !ok {
			return nil, nil, fmt.Errorf("expected string key")
		}
		var meta FieldMeta
		if err := dec.Decode(&meta); err != nil {
			return nil, nil, err
		}
		order = append(order, key)
		result[key] = meta
	}
	if tok, err := dec.Token(); err != nil || tok.(json.Delim) != '}' {
		return nil, nil, fmt.Errorf("object not closed")
	}
	return result, order, nil
}

func findConfigFile(root, name string) (string, error) {
	found := ""
	err := filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			return nil
		}
		if d.Name() == name {
			found = p
			return filepath.SkipDir
		}
		return nil
	})
	return found, err
}

// ---------- helpers ----------

func uniqueNonEmpty(list []string) []string {
	out := []string{}
	seen := map[string]struct{}{}
	for _, v := range list {
		if strings.TrimSpace(v) == "" {
			continue
		}
		clean := filepath.Clean(v)
		if _, ok := seen[clean]; ok {
			continue
		}
		seen[clean] = struct{}{}
		out = append(out, clean)
	}
	return out
}

func formatNumber(n float64) string {
	s := fmt.Sprintf("%.6f", n)
	s = strings.TrimRight(s, "0")
	s = strings.TrimSuffix(s, ".")
	return s
}

func shouldScaleByPoint01(fieldName string) bool {
	if strings.Contains(fieldName, "Pct") {
		return true
	}
	return fieldName == "AttackSpeed_Flat" ||
		fieldName == "ProjectileCooldown_Flat" ||
		fieldName == "SkillCooldown_Flat"
}

func transformValue(fieldName, raw string) string {
	raw = strings.TrimSpace(raw)
	if !shouldScaleByPoint01(fieldName) {
		return raw
	}
	tokens := kv.SplitWhitespace(raw)
	out := make([]string, len(tokens))
	for i, t := range tokens {
		num, err := strconvParse(t)
		if err == nil {
			out[i] = formatNumber(num * 0.01)
		} else {
			out[i] = t
		}
	}
	return strings.Join(out, " ")
}

func strconvParse(s string) (float64, error) {
	return strconv.ParseFloat(s, 64)
}

type abilityVarKey struct {
	isPct     bool
	varKey    string
	localeKey string
}

func buildAbilityVariableKey(field string) abilityVarKey {
	isPct := strings.Contains(field, "Pct")
	base := field
	for _, suf := range []string{"_Flat", "_Pct"} {
		base = strings.TrimSuffix(base, suf)
	}
	varKey := strings.ToLower(base)
	return abilityVarKey{
		isPct:     isPct,
		varKey:    varKey,
		localeKey: "dota_ability_variable_" + varKey,
	}
}

func lookupTokenValue(locKV *kv.KVObject, key string) (string, bool) {
	if direct, ok := locKV.GetString(key); ok {
		return direct, true
	}
	lang, ok := locKV.GetObject("lang")
	if !ok {
		return "", false
	}
	tokens, ok := lang.GetObject("Tokens")
	if !ok {
		return "", false
	}
	if val, ok := tokens.GetString(key); ok {
		return val, true
	}
	return "", false
}

func buildTooltipValueForField(fieldName string, locKV *kv.KVObject) string {
	if fieldName == "Level" {
		return "卡牌阶级："
	}
	info := buildAbilityVariableKey(fieldName)
	if !info.isPct {
		return "+$" + info.varKey
	}
	if cn, ok := lookupTokenValue(locKV, info.localeKey); ok && strings.TrimSpace(cn) != "" {
		return "+% " + strings.TrimSpace(cn)
	}
	return "+% " + info.varKey
}

// ---------- localization ----------

type localizeBaseItemsParams struct {
	pairName      string
	rawItemOrder  []string
	statsItems    *kv.KVObject
	rawItems      *kv.KVObject
	locKV         *kv.KVObject
	locText       string
	insertByIndex func(string, *insertIndexRef, []locEntry) string
	buildTooltip  func(string, *kv.KVObject) string
	getBonusOrder func(string) []string
	insertRef     *insertIndexRef
}

type locEntry struct {
	key   string
	value string
}

type localizeResult struct {
	locText   string
	insertRef *insertIndexRef
}

func localizeBaseItems(p localizeBaseItemsParams) localizeResult {
	locText := p.locText
	insertRef := p.insertRef

	if insertRef == nil {
		firstItem := p.rawItemOrder[0]
		bonusOrder := p.getBonusOrder(firstItem)
		if len(bonusOrder) > 0 {
			anchor := fmt.Sprintf(`DOTA_Tooltip_Ability_%s_%s`, firstItem, bonusOrder[0])
			re := regexp.MustCompile(`"Tokens"\s*\{([\s\S]*?)\n\}`)
			if m := re.FindStringSubmatchIndex(locText); m != nil {
				body := locText[m[2]:m[3]]
				lines := strings.Split(body, "\n")
				for i, line := range lines {
					if strings.Contains(line, fmt.Sprintf(`"%s"`, anchor)) {
						insertRef = &insertIndexRef{Value: i + 1}
						break
					}
				}
			}
		}
	}

	if insertRef == nil {
		return localizeResult{locText: locText, insertRef: nil}
	}

	for _, itemName := range p.rawItemOrder {
		statsItem, _ := p.statsItems.GetObject(itemName)
		rawItem, _ := p.rawItems.GetObject(itemName)
		if statsItem == nil || rawItem == nil {
			continue
		}
		abilityValues, _ := rawItem.GetObject("AbilityValues")
		locEntries := []locEntry{}
		desiredKeys := map[string]struct{}{}
		ordered := buildOrderedFields(abilityValues, statsItem, p.getBonusOrder(itemName))
		for _, field := range ordered {
			if field != "Level" {
				if bonus, ok := statsItem.GetObject("BonusAttribute"); ok {
					if _, ok := bonus.Get(field); !ok {
						continue
					}
				}
			}

			locKey := fmt.Sprintf(`DOTA_Tooltip_Ability_%s_%s`, itemName, field)
			desiredKeys[locKey] = struct{}{}
			if strings.Contains(locText, fmt.Sprintf(`"%s"`, locKey)) {
				continue
			}
			val := p.buildTooltip(field, p.locKV)
			if val == "" {
				continue
			}
			locEntries = append(locEntries, locEntry{key: locKey, value: val})
		}

		if len(desiredKeys) > 0 {
			locText = removeStaleAttributeLocalization(locText, insertRef, itemName, desiredKeys)
		}
		if len(locEntries) > 0 {
			locText = p.insertByIndex(locText, insertRef, locEntries)
		}
	}

	return localizeResult{locText: locText, insertRef: insertRef}
}

func buildOrderedFields(av *kv.KVObject, statsItem *kv.KVObject, bonusOrder []string) []string {
	if av == nil {
		return []string{}
	}
	if len(bonusOrder) > 0 {
		order := append([]string{}, bonusOrder...)
		if av.Has("Level") && !contains(order, "Level") {
			order = append(order, "Level")
		}
		return order
	}
	if bonus, ok := statsItem.GetObject("BonusAttribute"); ok {
		order := append([]string{}, bonus.Keys...)
		if av.Has("Level") && !contains(order, "Level") {
			order = append(order, "Level")
		}
		return order
	}
	return append([]string{}, av.Keys...)
}

func contains(arr []string, k string) bool {
	for _, v := range arr {
		if v == k {
			return true
		}
	}
	return false
}

func removeStaleAttributeLocalization(locText string, insertRef *insertIndexRef, itemName string, desiredKeys map[string]struct{}) string {
	re := regexp.MustCompile(`"Tokens"\s*\{([\s\S]*?)\n\}`)
	m := re.FindStringSubmatchIndex(locText)
	if m == nil {
		return locText
	}
	body := locText[m[2]:m[3]]
	bodyStart := m[2]
	bodyEnd := m[3]

	lines := strings.Split(body, "\n")
	prefix := fmt.Sprintf("DOTA_Tooltip_Ability_%s_", itemName)
	removed := []int{}
	kept := make([]string, 0, len(lines))
	for idx, line := range lines {
		m := regexp.MustCompile(`^\s*"([^"]+)"`).FindStringSubmatch(line)
		if len(m) != 2 {
			kept = append(kept, line)
			continue
		}
		key := m[1]
		if !strings.HasPrefix(key, prefix) {
			kept = append(kept, line)
			continue
		}
		if _, ok := desiredKeys[key]; ok {
			kept = append(kept, line)
			continue
		}
		suffix := strings.TrimPrefix(key, prefix)
		if shouldKeepNonAttributeSuffix(suffix) {
			kept = append(kept, line)
			continue
		}
		removed = append(removed, idx)
	}

	if len(removed) == 0 {
		return locText
	}

	if insertRef != nil {
		count := 0
		for _, idx := range removed {
			if idx < insertRef.Value {
				count++
			}
		}
		insertRef.Value = max(0, insertRef.Value-count)
	}

	newBody := strings.Join(kept, "\n")
	return locText[:bodyStart] + newBody + locText[bodyEnd:]
}

func shouldKeepNonAttributeSuffix(suffix string) bool {
	if strings.HasSuffix(suffix, "Description") {
		return true
	}
	if strings.Contains(suffix, "SummaryDescription") {
		return true
	}
	return suffix == "Lore" || suffix == "Notes" || suffix == "Note"
}

