func renderKVBlock(key string, obj *kv.KVObject) string {
	return fmt.Sprintf("\"%s\"\n{\n%s}\n", key, kvToString(obj, 1))
}

func kvToString(obj *kv.KVObject, indent int) string {
	pad := strings.Repeat("\t", indent)
	var b strings.Builder
	for _, k := range obj.Keys {
		v := obj.Values[k]
		switch vv := v.(type) {
		case string:
			b.WriteString(fmt.Sprintf("%s\"%s\"\t\t\"%s\"\n", pad, k, vv))
		case *kv.KVObject:
			b.WriteString(fmt.Sprintf("%s\"%s\"\n", pad, k))
			b.WriteString(fmt.Sprintf("%s{\n", pad))
			b.WriteString(kvToString(vv, indent+1))
			b.WriteString(fmt.Sprintf("%s}\n", pad))
		}
	}
	return b.String()
}

