func generateDerivedItemLua(baseLuaPath string, level int, overwrite bool) {
	if _, err := os.Stat(baseLuaPath); errors.Is(err, os.ErrNotExist) {
		return
	}
	dir := filepath.Dir(baseLuaPath)
	baseName := strings.TrimSuffix(filepath.Base(baseLuaPath), ".lua")
	derivedName := fmt.Sprintf("%s_%d", baseName, level)
	derivedPath := filepath.Join(dir, derivedName+".lua")

	if _, err := os.Stat(derivedPath); err == nil && !overwrite {
		return
	}

	data, err := os.ReadFile(baseLuaPath)
	if err != nil {
		return
	}

	re := regexp.MustCompile(`\b` + regexp.QuoteMeta(baseName) + `\b`)
	out := re.ReplaceAllString(string(data), derivedName)
	_ = os.WriteFile(derivedPath, []byte(out), 0o644)
}

