type expandItemsParams struct {
	rawItems      *kv.KVObject
	baseOrder     []string
	maxLevelMap   map[string]int
	managedFields map[string]struct{}
}

func expandItemsByLevel(p expandItemsParams) {
	newOrder := []string{}
	newItems := kv.NewKVObject()

	for _, baseKey := range p.baseOrder {
		base, _ := p.rawItems.GetObject(baseKey)
		if base == nil {
			continue
		}
		newOrder = append(newOrder, baseKey)
		newItems.Set(baseKey, base)

		baseAV, _ := base.GetObject("AbilityValues")
		if baseAV == nil {
			continue
		}
		baseAVKeys := append([]string{}, baseAV.Keys...)
		maxLevel := p.maxLevelMap[baseKey]
		if maxLevel <= 1 {
			continue
		}

		for lvl := 1; lvl <= maxLevel; lvl++ {
			key := fmt.Sprintf("%s_%d", baseKey, lvl)
			oldDerived, _ := p.rawItems.GetObject(key)
			cloned := base.DeepClone()
			cloned.Set("Shop", "-1")
			for _, k := range cloned.Keys {
				if k == "AbilityValues" {
					continue
				}
				if v, ok := cloned.GetString(k); ok {
					tokens := kv.SplitWhitespace(v)
					if shouldPickByLevel(v, tokens) {
						cloned.Set(k, pickByLevel(tokens, lvl-1))
					}
				}
			}

			if oldDerived != nil {
				for _, k := range oldDerived.Keys {
					if _, exists := cloned.Values[k]; exists {
						continue
					}
					if _, managed := p.managedFields[k]; managed {
						continue
					}
					cloned.Set(k, oldDerived.Values[k])
				}
			}

			// AbilityTextureName 派生：基于 base 名追加 -XX
			if baseTex, ok := base.GetString("AbilityTextureName"); ok {
				lvlStr := fmt.Sprintf("%02d", lvl)
				cloned.Set("AbilityTextureName", fmt.Sprintf("%s-%s", baseTex, lvlStr))
			}

			// ScriptFile 派生：沿用目录，文件名替换为 baseKey_lvl.lua
			if baseScript, ok := base.GetString("ScriptFile"); ok {
				lastSlash := strings.LastIndex(baseScript, "/")
				dir := ""
				if lastSlash >= 0 {
					dir = baseScript[:lastSlash+1]
				}
				cloned.Set("ScriptFile", fmt.Sprintf("%s%s_%d.lua", dir, baseKey, lvl))
			}

			avFinal := kv.NewKVObject()
			for _, field := range baseAVKeys {
				rawVal, ok := baseAV.GetString(field)
				if !ok {
					continue
				}
				if field == "Level" {
					avFinal.Set(field, fmt.Sprintf("%d", lvl))
					continue
				}
				tokens := kv.SplitWhitespace(rawVal)
				if shouldPickByLevel(rawVal, tokens) {
					avFinal.Set(field, pickByLevel(tokens, lvl-1))
				} else {
					avFinal.Set(field, rawVal)
				}
			}
			cloned.Set("AbilityValues", avFinal)
			newOrder = append(newOrder, key)
			newItems.Set(key, cloned)
		}
	}

	p.rawItems.Keys = []string{}
	p.rawItems.Values = map[string]kv.KVValue{}
	for _, k := range newOrder {
		p.rawItems.Set(k, newItems.Values[k])
	}
}

func shouldPickByLevel(raw string, tokens []string) bool {
	if len(tokens) <= 1 {
		return false
	}
	if strings.Contains(raw, "|") {
		return false
	}
	return true
}

func pickByLevel(tokens []string, idx int) string {
	if len(tokens) == 0 {
		return ""
	}
	if idx < 0 {
		idx = 0
	}
	if idx >= len(tokens) {
		idx = len(tokens) - 1
	}
	return tokens[idx]
}

// ---------- ability / level helpers ----------

func getMaxLevelFromStatsItem(item *kv.KVObject) int {
	if item == nil {
		return 1
	}
	for _, k := range item.Keys {
		if v, ok := item.GetString(k); ok {
			tokens := kv.SplitWhitespace(v)
			if len(tokens) > 1 {
				return len(tokens)
			}
		}
	}
	return 1
}

// ---------- bonus attribute order ----------

func getBonusAttributeOrder(tokens []kv.Token, itemName string) []string {
	order := []string{}
	i := 0
	for i < len(tokens) {
		tk := tokens[i]
		if tk.Typ == "str" && tk.Val == itemName {
			if i+1 < len(tokens) && tokens[i+1].Typ == "{" {
				i += 2
				depth := 1
				for i < len(tokens) && depth > 0 {
					cur := tokens[i]
					if cur.Typ == "{" {
						depth++
						i++
						continue
					}
					if cur.Typ == "}" {
						depth--
						i++
						continue
					}
					if depth == 1 && cur.Typ == "str" && cur.Val == "BonusAttribute" {
						if i+1 < len(tokens) && tokens[i+1].Typ == "{" {
							i += 2
							bDepth := 1
							for i < len(tokens) && bDepth > 0 {
								bt := tokens[i]
								if bt.Typ == "{" {
									bDepth++
									i++
									continue
								}
								if bt.Typ == "}" {
									bDepth--
									i++
									continue
								}
								if bDepth == 1 && bt.Typ == "str" {
									if i+1 < len(tokens) && tokens[i+1].Typ == "str" {
										order = append(order, bt.Val)
										i += 2
										continue
									}
								}
								i++
							}
							return order
						}
					}
					i++
				}
				break
			}
		}
		i++
	}
	return order
}

// ---------- auto cast dummies ----------

func ensureAutoCastDummies(resolve func(string) string, resolveForWrite func(string) string, heroMax map[string]int) er
ror {
	if len(heroMax) == 0 {
		fmt.Println("[auto-dummy] skip: no heroes with max level info")
		return nil
	}

	dummyPath := resolveForWrite(filepath.Join("game/dzsj/scripts/npc/units", "npc_dota_auto_cast_dummy.txt"))
	dummyText, err := kv.ReadFileIfExists(dummyPath)
	if err != nil || strings.TrimSpace(dummyText) == "" {
		return fmt.Errorf("dummy file missing or empty: %s", dummyPath)
	}

	heroesPath := resolve(filepath.Join("game/dzsj/excel/Dota2 原版游戏配置", "npc_heroes.txt"))
	heroesText, err := kv.ReadFileIfExists(heroesPath)
	if err != nil || strings.TrimSpace(heroesText) == "" {
		return fmt.Errorf("read heroes text: %w", err)
	}

	defaultWearPath := resolve(filepath.Join("game/dzsj/scripts/npc/utils", "default.txt"))
	defaultText, err := kv.ReadFileIfExists(defaultWearPath)
	if err != nil || strings.TrimSpace(defaultText) == "" {
		return fmt.Errorf("read default wearables: %w", err)
	}

	fmt.Printf("[auto-dummy] heroes to check: %v\n", heroMax)

	var newBlocks []string

	maxNeed := 0
	for _, lvl := range heroMax {
		if lvl > maxNeed {
			maxNeed = lvl
		}
	}
	if maxNeed < 1 {
		maxNeed = 1
	}

	templateBlocks := map[int]string{}
