// renderDummyBlock replaces key/Model/ModelScale/AttachWearables using raw template text (tolerant to non-standard for
matting).
func renderDummyBlock(templateRaw, newKey, model, modelScale string, wearEntries []wearableEntry, level int) string {
	out := templateRaw

	reKey := regexp.MustCompile(`"npc_dota_auto_cast_dummy_drow_ranger_\d+"`)
	out = reKey.ReplaceAllString(out, fmt.Sprintf("\"%s\"", newKey))

	reModel := regexp.MustCompile(`"Model"\s*"[^"]*"`)
	out = reModel.ReplaceAllString(out, fmt.Sprintf("\"Model\"\t\t\"%s\"", model))

	if strings.TrimSpace(modelScale) != "" {
		reModelScale := regexp.MustCompile(`"ModelScale"\s*"[^"]*"`)
		if reModelScale.MatchString(out) {
			out = reModelScale.ReplaceAllString(out, fmt.Sprintf("\"ModelScale\"\t\t\"%s\"", modelScale))
		} else {
			reModelLine := regexp.MustCompile(`(?m)^([ \t]*)"Model"\s*"[^"]*"[ \t]*(\r?\n)?`)
			loc := reModelLine.FindStringSubmatchIndex(out)
			if loc != nil {
				indent := out[loc[2]:loc[3]]
				insertPos := insertAfterLine(out, loc)
				out = out[:insertPos] + indent + fmt.Sprintf("\"ModelScale\"\t\t\"%s\"\n", modelScale) + out[insertPos:]
			} else {
				out = out + "\n" + fmt.Sprintf("\"ModelScale\"\t\t\"%s\"\n", modelScale)
			}
		}
	}

	reOffset := regexp.MustCompile(`(?m)^[ \t]*"Offset"[ \t]*"[^"]*"[ \t]*\r?\n?`)
	out = reOffset.ReplaceAllString(out, "")
	if level == 2 || level == 3 {
		reModelScaleLine := regexp.MustCompile(`(?m)^([ \t]*)"ModelScale"\s*"[^"]*"[ \t]*(\r?\n)?`)
		loc := reModelScaleLine.FindStringSubmatchIndex(out)
		if loc != nil {
			indent := out[loc[2]:loc[3]]
			insertPos := insertAfterLine(out, loc)
			out = out[:insertPos] + indent + "\"Offset\"\t\t\"30\"\n" + out[insertPos:]
		} else {
			reModelLine := regexp.MustCompile(`(?m)^([ \t]*)"Model"\s*"[^"]*"[ \t]*(\r?\n)?`)
			loc = reModelLine.FindStringSubmatchIndex(out)
			if loc != nil {
				indent := out[loc[2]:loc[3]]
				insertPos := insertAfterLine(out, loc)
				out = out[:insertPos] + indent + "\"Offset\"\t\t\"30\"\n" + out[insertPos:]
			} else {
				out = out + "\n" + "\"Offset\"\t\t\"30\"\n"
			}
		}
	}

	// Remove any direct Wearable entries from the template; we'll inject AttachWearables.
	reWearableLine := regexp.MustCompile(`(?m)^\s*"Wearable\d+"\s*\{[^\}]*\}\s*(//.*)?\s*$\n?`)
	out = reWearableLine.ReplaceAllString(out, "")

	var attachBuilder strings.Builder
	attachBuilder.WriteString("\t\t\"AttachWearables\"\n\t\t{\n")
	for i, entry := range wearEntries {
		comment := ""
		if entry.Comment != "" {
			comment = " //" + entry.Comment
		}
		attachBuilder.WriteString(fmt.Sprintf("\t\t      \"Wearable%d\"\t\t{	\"ItemDef\"\t\t\"%s\"\t\t}%s\n", i+1, entry.ID, 
comment))
	}
	attachBuilder.WriteString("\t\t}")
	attachBlock := attachBuilder.String()

	reAttach := regexp.MustCompile(`"AttachWearables"\s*\{[\s\S]*?\}`)
	if reAttach.MatchString(out) {
		out = reAttach.ReplaceAllString(out, attachBlock)
	} else {
		reCreature := regexp.MustCompile(`"Creature"\s*\{`)
		loc := reCreature.FindStringIndex(out)
		if loc != nil {
			insertPos := loc[1]
			out = out[:insertPos] + "\n" + attachBlock + out[insertPos:]
		} else {
			// fallback append at end
			out = out + "\n" + attachBlock + "\n"
		}
	}

	return out
}

func insertAfterLine(s string, loc []int) int {
	if loc == nil || len(loc) < 2 {
		return 0
	}
	lineStart := loc[0]
	if lineStart < 0 || lineStart >= len(s) {
		return loc[1]
	}
	lineEndRel := strings.IndexByte(s[lineStart:], '\n')
	if lineEndRel >= 0 {
		return lineStart + lineEndRel + 1
	}
	return loc[1]
}

// extract a KV block text by key using brace matching (ignores parse errors elsewhere)
func extractKVBlock(text, key string) (string, bool) {
	keyQuoted := fmt.Sprintf("\"%s\"", key)
	re := regexp.MustCompile(`(?m)^[ \t]*` + regexp.QuoteMeta(keyQuoted) + `[ \t]*`)
	loc := re.FindStringIndex(text)
	if loc == nil {
		return "", false
	}
	idx := loc[0]
	braceStart := strings.Index(text[loc[1]:], "{")
	if braceStart < 0 {
		return "", false
	}
	start := loc[1] + braceStart
	depth := 0
	inStr := false
	escape := false
	for i := start; i < len(text); i++ {
		ch := text[i]
		if inStr {
			if escape {
				escape = false
				continue
			}
			if ch == '\\' {
				escape = true
				continue
			}
			if ch == '"' {
				inStr = false
			}
			continue
		}
		if ch == '"' {
			inStr = true
			continue
		}
		if ch == '{' {
			depth++
			continue
		}
		if ch == '}' {
			depth--
			if depth == 0 {
				end := i + 1
				return text[idx:end], true
			}
			continue
		}
	}
	return "", false
}

func parseSingleBlock(block string) (*kv.KVObject, error) {
	wrapped := fmt.Sprintf("root\n{\n%s\n}\n", block)
	toks := kv.TokenizeKV(wrapped)
	obj, err := kv.ParseKV(toks)
	if err != nil {
		return nil, err
	}
	root, ok := obj.GetObject("root")
	if !ok {
		return nil, fmt.Errorf("missing root in parsed block")
	}
	return root, nil
}

var (
	reBlockComment = regexp.MustCompile(`(?s)/\*.*?\*/`)
	reLineComment  = regexp.MustCompile(`//.*?$`)
)

func stripKVComments(s string) string {
	s = reBlockComment.ReplaceAllString(s, "")
	s = reLineComment.ReplaceAllString(s, "")
	return s
}

func extractKVStringValue(block, key string) (string, bool) {
	clean := stripKVComments(block)
	re := regexp.MustCompile(fmt.Sprintf(`"%s"\s*"([^"]*)"`, regexp.QuoteMeta(key)))
	m := re.FindStringSubmatch(clean)
	if len(m) != 2 {
		return "", false
	}
	return m[1], true
}

// ---------- lua ----------

func generateDerivedItemLua(baseLuaPath string, level int, overwrite bool) {
	if _, err := os.Stat(baseLuaPath); errors.Is(err, os.ErrNotExist) {
		return
	}
	dir := filepath.Dir(baseLuaPath)
	baseName := strings.TrimSuffix(filepath.Base(baseLuaPath), ".lua")
	derivedName := fmt.Sprintf("%s_%d", baseName, level)
	derivedPath := filepath.Join(dir, derivedName+".lua")

	if _, err := os.Stat(derivedPath); err == nil && !overwrite {
		return
	}

	data, err := os.ReadFile(baseLuaPath)
	if err != nil {
		return
	}

	re := regexp.MustCompile(`\b` + regexp.QuoteMeta(baseName) + `\b`)
	out := re.ReplaceAllString(string(data), derivedName)
	_ = os.WriteFile(derivedPath, []byte(out), 0o644)
}

