			folder: "game/dzsj/scripts/npc/heroes",
			output: "game/dzsj/scripts/npc/npc_heroes_custom.txt",
			root:   "DOTAHeroes",
		},
	}

	for _, t := range targets {
		dirAbs := resolve(t.folder)
		if info, err := os.Stat(dirAbs); err != nil || !info.IsDir() {
			fmt.Printf("[kv-merge] skip %s: folder missing: %s\n", t.name, dirAbs)
			continue
		}
		files, err := listKVFiles(dirAbs)
		if err != nil {
			return fmt.Errorf("list %s files: %w", t.name, err)
		}
		if len(files) == 0 {
			fmt.Printf("[kv-merge] skip %s: no kv files in %s\n", t.name, dirAbs)
			continue
		}

		var merged strings.Builder
		for _, file := range files {
			data, err := os.ReadFile(file)
			if err != nil {
				return fmt.Errorf("read kv (%s): %w", file, err)
			}
			merged.WriteString(indentNonEmptyLines(string(data)))
			if merged.Len() > 0 && !strings.HasSuffix(merged.String(), "\n") {
				merged.WriteString("\n")
			}
		}

		out := fmt.Sprintf("\"%s\"\n{\n%s\n}", t.root, merged.String())
		outPath := resolveForWrite(t.output)
		if err := os.WriteFile(outPath, []byte(out), 0o644); err != nil {
			return fmt.Errorf("write merged %s: %w", t.output, err)
		}
		fmt.Printf("[kv-merge] wrote %s from %d files\n", outPath, len(files))
	}

	return nil
}

func listKVFiles(dirAbs string) ([]string, error) {
	files := []string{}
	err := filepath.WalkDir(dirAbs, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			return nil
		}
		if strings.EqualFold(filepath.Ext(d.Name()), ".txt") {
			files = append(files, p)
		}
		return nil
	})
	sort.Strings(files)
	return files, err
}

func indentNonEmptyLines(s string) string {
	if s == "" {
		return s
	}
	lines := strings.Split(s, "\n")
	for i, line := range lines {
		if strings.TrimSpace(line) == "" {
			continue
		}
		lines[i] = "    " + line
	}
	return strings.Join(lines, "\n")
}

