					return getBonusAttributeOrder(statsTokens, item)
				},
				insertRef: insertRef,
			})
			locText = res.locText
			if insertRef == nil && res.insertRef != nil {
				insertRef = res.insertRef
			}

			locText = expandLocalizationByLevel(expandLocalizationParams{
				rawItemOrder:  []string{itemName},
				rawItems:      rawItems,
				statsItems:    statsItems,
				locKV:         locKV,
				locText:       locText,
				insertRef:     insertRef,
				insertByIndex: insertLocalizationByIndex,
				buildTooltip:  buildTooltipValueForField,
				maxLevelMap:   maxLevelMap,
			})

			baseLuaPath := resolveForWrite(filepath.Join(
				"game/dzsj/scripts/vscripts/abilities",
				fmt.Sprintf("%s.lua", itemName),
			))

			if _, err := os.Stat(baseLuaPath); errors.Is(err, os.ErrNotExist) && fallbackLuaPath != "" {
				if data, err := os.ReadFile(fallbackLuaPath); err == nil {
					baseData := string(data)
					repl := regexp.MustCompile(`\b` + regexp.QuoteMeta(fallbackLuaName) + `\b`)
					out := repl.ReplaceAllString(baseData, itemName)
					_ = os.MkdirAll(filepath.Dir(baseLuaPath), fs.ModePerm)
					_ = os.WriteFile(baseLuaPath, []byte(out), 0o644)
				}
			}

			for lvl := 1; lvl <= maxLevelMap[itemName]; lvl++ {
				generateDerivedItemLua(baseLuaPath, lvl, false)
			}
		}

		expandItemsByLevel(expandItemsParams{
			rawItems:      rawItems,
			baseOrder:     rawItemOrder,
			maxLevelMap:   maxLevelMap,
			managedFields: managedFields,
		})

		if err := kv.WriteKVFile(ctx.rawAbs, ctx.rawItems); err != nil {
			return fmt.Errorf("write raw kv: %w", err)
		}
	}

	if err := ensureAutoCastDummies(resolve, resolveForWrite, heroMaxLevel); err != nil {
		return err
	}

	locText = normalizeTokensBlankLines(locText)
	if err := os.MkdirAll(filepath.Dir(locPath), fs.ModePerm); err != nil {
		return fmt.Errorf("ensure localization dir: %w", err)
	}
	if err := os.WriteFile(locPath, []byte(locText), 0o644); err != nil {
		return fmt.Errorf("write localization: %w", err)
	}

	if err := mergeNpcKVs(resolve, resolveForWrite); err != nil {
		return err
	}

	return nil
}

// ---------- config ----------

func loadConfig(workspaceRoot string) (*loadedConfig, error) {
	cfgName := "dzsj.kv-sync.json"
	found, err := findConfigFile(workspaceRoot, cfgName)
	if err != nil {
		return nil, err
	}
	if found == "" {
		return nil, fmt.Errorf("missing config %s", cfgName)
	}
	data, err := os.ReadFile(found)
	if err != nil {
		return nil, err
	}

	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return nil, err
	}

	cfg := &PluginConfig{}

	if pairsRaw, ok := raw["pairs"]; ok {
		if err := json.Unmarshal(pairsRaw, &cfg.Pairs); err != nil {
			return nil, fmt.Errorf("parse pairs: %w", err)
		}
	}

	if locRaw, ok := raw["localizationFile"]; ok {
		if err := json.Unmarshal(locRaw, &cfg.LocalizationFile); err != nil {
			return nil, fmt.Errorf("parse localizationFile: %w", err)
		}
	}
	if lvRaw, ok := raw["Level"]; ok {
		if err := json.Unmarshal(lvRaw, &cfg.Level); err != nil {
			return nil, fmt.Errorf("parse Level: %w", err)
		}
	}

	if ftRaw, ok := raw["fieldTable"]; ok {
		m, order, err := parseOrderedFieldMeta(ftRaw)
		if err != nil {
			return nil, fmt.Errorf("parse fieldTable: %w", err)
		}
		cfg.FieldTable = m
		cfg.FieldTableOrder = order
	}

	if ftRaw, ok := raw["fieldTable2"]; ok {
		m, order, err := parseOrderedFieldMeta(ftRaw)
		if err != nil {
			return nil, fmt.Errorf("parse fieldTable2: %w", err)
		}
		cfg.FieldTable2 = m
		cfg.FieldTable2Order = order
	}

	return &loadedConfig{cfg: cfg, cfgPath: found}, nil
}

func parseOrderedFieldMeta(raw json.RawMessage) (map[string]FieldMeta, []string, error) {
	dec := json.NewDecoder(bytes.NewReader(raw))
	tok, err := dec.Token()
	if err != nil {
		return nil, nil, err
	}
	delim, ok := tok.(json.Delim)
	if !ok || delim != '{' {
		return nil, nil, fmt.Errorf("expected object")
	}
	result := map[string]FieldMeta{}
	order := []string{}
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return nil, nil, err
		}
		key, ok := keyTok.(string)
		if !ok {
			return nil, nil, fmt.Errorf("expected string key")
		}
		var meta FieldMeta
		if err := dec.Decode(&meta); err != nil {
			return nil, nil, err
		}
		order = append(order, key)
		result[key] = meta
	}
	if tok, err := dec.Token(); err != nil || tok.(json.Delim) != '}' {
		return nil, nil, fmt.Errorf("object not closed")
	}
	return result, order, nil
}

func findConfigFile(root, name string) (string, error) {
	found := ""
	err := filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			return nil
		}
		if d.Name() == name {
			found = p
			return filepath.SkipDir
		}
		return nil
	})
	return found, err
}

// ---------- helpers ----------

func uniqueNonEmpty(list []string) []string {
	out := []string{}
	seen := map[string]struct{}{}
	for _, v := range list {
		if strings.TrimSpace(v) == "" {
			continue
		}
		clean := filepath.Clean(v)
		if _, ok := seen[clean]; ok {
			continue
		}
		seen[clean] = struct{}{}
		out = append(out, clean)
	}
	return out
}

func formatNumber(n float64) string {
	s := fmt.Sprintf("%.6f", n)
	s = strings.TrimRight(s, "0")
	s = strings.TrimSuffix(s, ".")
	return s
}

func shouldScaleByPoint01(fieldName string) bool {
	if strings.Contains(fieldName, "Pct") {
		return true
	}
	return fieldName == "AttackSpeed_Flat" ||
		fieldName == "ProjectileCooldown_Flat" ||
		fieldName == "SkillCooldown_Flat"
}

func transformValue(fieldName, raw string) string {
	raw = strings.TrimSpace(raw)
	if !shouldScaleByPoint01(fieldName) {
		return raw
	}
	tokens := kv.SplitWhitespace(raw)
	out := make([]string, len(tokens))
	for i, t := range tokens {
		num, err := strconvParse(t)
		if err == nil {
			out[i] = formatNumber(num * 0.01)
		} else {
			out[i] = t
		}
	}
	return strings.Join(out, " ")
}

func strconvParse(s string) (float64, error) {
	return strconv.ParseFloat(s, 64)
}

type abilityVarKey struct {
	isPct     bool
	varKey    string
	localeKey string
}

func buildAbilityVariableKey(field string) abilityVarKey {
	isPct := strings.Contains(field, "Pct")
	base := field
	for _, suf := range []string{"_Flat", "_Pct"} {
		base = strings.TrimSuffix(base, suf)
	}
	varKey := strings.ToLower(base)
	return abilityVarKey{
		isPct:     isPct,
		varKey:    varKey,
		localeKey: "dota_ability_variable_" + varKey,
	}
}

func lookupTokenValue(locKV *kv.KVObject, key string) (string, bool) {
	if direct, ok := locKV.GetString(key); ok {
		return direct, true
	}
	lang, ok := locKV.GetObject("lang")
	if !ok {
		return "", false
	}
	tokens, ok := lang.GetObject("Tokens")
	if !ok {
		return "", false
	}
	if val, ok := tokens.GetString(key); ok {
		return val, true
	}
	return "", false
}

func buildTooltipValueForField(fieldName string, locKV *kv.KVObject) string {
	if fieldName == "Level" {
		return "卡牌阶级："
	}
	info := buildAbilityVariableKey(fieldName)
	if !info.isPct {
		return "+$" + info.varKey
	}
	if cn, ok := lookupTokenValue(locKV, info.localeKey); ok && strings.TrimSpace(cn) != "" {
		return "+% " + strings.TrimSpace(cn)
	}
	return "+% " + info.varKey
}

